<template><section class="join-step"><header><span>그럼우리</span><button @click="logout">로그아웃</button></header><p v-if="error" role="alert">{{error}}</p><template v-if="loaded"><template v-if="stage==='photos'"><h1>프로필 사진</h1><PhotoEditor @changed="photosChanged"/><button class="next" :disabled="images.length<2||busy" @click="stage='selfie'">다음</button></template><template v-else-if="stage==='selfie'"><h1>셀피 확인</h1><p v-if="selfie?.note">{{selfie.note}}</p><SelfieCaptureDialog ref="capture" required @submitted="submitted"/><button class="next" :disabled="busy" @click="capture.open()">촬영하기</button><button class="back" @click="stage='photos'">이전</button></template><template v-else><div class="review-wait"><div class="review-symbol" aria-hidden="true"><span>♥</span><i/></div><h1>조금만 기다려 주세요</h1><p>프로필을 확인하고 있어요.<br/>심사가 완료되면 바로 시작할 수 있어요.</p><p v-if="status?.reviewComment&&status.status==='REJECTED'">{{status.reviewComment}}</p><button class="back" @click="load">심사 상태 확인</button></div></template></template><p v-else>불러오는 중…</p></section></template>
<script setup>
import {ref,onMounted,onUnmounted} from 'vue';import {useRouter} from 'vue-router';import api from '../../api/api';import {clearToken} from '../../utils/auth';import PhotoEditor from '../../components/PhotoEditor.vue';import SelfieCaptureDialog from '../../components/SelfieCaptureDialog.vue';
const router=useRouter(),images=ref([]),status=ref(),selfie=ref(),capture=ref(),stage=ref('photos'),loaded=ref(false),busy=ref(false),error=ref('');let timer,disposed=false;
async function load(){try{const [s,p,f]=await Promise.all([api.get('/profile-images/review-status'),api.get('/profile-images/me'),api.get('/selfie')]);if(disposed)return;status.value=s.data;images.value=p.data;selfie.value=f.data;if(s.data.status==='ACTIVE'){router.replace('/today');return;}if(images.value.length<2)stage.value='photos';else if(['PENDING','APPROVED'].includes(selfie.value?.state)&&s.data.status!=='REJECTED')stage.value='waiting';else if(!loaded.value||stage.value==='waiting')stage.value='selfie';loaded.value=true;}catch(e){error.value=e.response?.data?.message||'상태를 확인하지 못했어요.';}}
async function photosChanged(data){images.value=data;}
async function submitted(){busy.value=true;error.value='';try{await api.post('/profile-images/review-submit');await load();}catch(e){error.value=e.response?.data?.message||'심사를 신청하지 못했어요.';await load();}finally{busy.value=false;}}
function logout(){clearToken();router.replace('/');}onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load();},5000);});onUnmounted(()=>{disposed=true;clearInterval(timer);});
</script><style scoped>.review-wait{min-height:65dvh;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center}.review-symbol{position:relative;width:96px;height:96px;display:grid;place-items:center;background:#f8e6dc;border-radius:32px;margin-bottom:24px;color:#cf7959;font-size:40px}.review-symbol i{position:absolute;right:0;bottom:0;width:22px;height:22px;border:5px solid #fffaf7;background:#d89270;border-radius:50%}.review-wait h1{font-size:23px;letter-spacing:-.7px;margin:8px 0}.review-wait p{color:#9b8174;margin-bottom:30px}.review-wait .back{border:1px solid #ead9cf;background:white;padding:12px 26px}.join-step{box-sizing:border-box;max-width:480px;min-height:100dvh;margin:auto;padding:24px 20px;background:#fffaf7;color:#40332b}.join-step header{display:flex;justify-content:space-between;align-items:center;margin-bottom:36px}.join-step h1{font-size:24px}.join-step p{font-size:14px;line-height:1.7}.join-step button{border:0;border-radius:12px;padding:12px 18px;cursor:pointer;font:inherit;background:#eee1d8;color:#604636}.join-step .next{display:block;width:100%;background:#d56f4e;color:white;margin:24px 0 12px}.join-step button:disabled{opacity:.5}.join-step .back{background:transparent}[role=alert]{color:#a63825}</style>